import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { openDatabase } from '../../src/db/connection.js';
import { BookmarkStore } from '../../src/models/bookmarks.js';

let db;
let store;
before(async () => {
  db = openDatabase(':memory:');
  store = new BookmarkStore(db);
  // Seed 1,000 bookmarks directly (bypassing network title fetch).
  for (let i = 0; i < 1000; i++) {
    await store.create({
      address: `https://site${i}.example.com/page`,
      title: `Bookmark number ${i}`,
      description: i % 2 === 0 ? 'even entry' : 'odd entry',
      tags: [i % 10 === 0 ? 'tenth' : 'general'],
    });
  }
});
after(() => db.close());

test('search over 1,000 bookmarks returns in under 1s (SC-003)', () => {
  const start = performance.now();
  const results = store.list({ q: 'number 500' });
  const elapsed = performance.now() - start;
  assert.ok(results.length >= 1);
  assert.ok(elapsed < 1000, `search took ${elapsed.toFixed(1)}ms`);
});

test('tag filter over 1,000 bookmarks returns in under 1s', () => {
  const start = performance.now();
  const results = store.list({ tag: 'tenth' });
  const elapsed = performance.now() - start;
  assert.equal(results.length, 100);
  assert.ok(elapsed < 1000, `filter took ${elapsed.toFixed(1)}ms`);
});

